package main

import (
	"fmt"
	"strings"
)

func kind(n int) string {
	if n < 0 {
		return "neg"
	} else if n == 0 {
		return "zero"
	} else if n < 10 {
		for i := 0; i < n; i++ {
			if i == 5 {
				return "five"
			}
		}
		return "small"
	}
	return strings.ToUpper("pos")
}

// main prints one kind.
func main() {
	fmt.Println(kind(1))
}

package main

import "testing"

func TestKind(t *testing.T) {
	if kind(0) != "zero" {
		t.Fatal(kind(0))
	}
}
